import { useMemo, useState } from "react";
import { Toggle } from "@/shared/ui/controls/Toggle";
import { Button } from "@/shared/ui/controls/Button";
import { SearchField } from "@/shared/ui/controls/SearchField";
import { ModalCard } from "@/shared/ui/overlay/ModalCard";
import { Box } from "@/shared/ui/layout/Box";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Grid } from "@/shared/ui/layout/Grid";
import { Text } from "@/shared/ui/typography/Text";

// Vendored from `@/shared/data/skills` (unresolvable in this sandbox — the real KIND/SOURCE_TAG are
// fine as-is, pure data; the SKILLS catalog itself loads via a Vite import.meta.glob, unsupported
// here, so sample skills are fabricated below instead) — unchanged.
const KIND = {
  workflow: { label: "workflow", glyph: "⌁", color: "var(--accent)" },
  scaffold: { label: "scaffold", glyph: "▤", color: "var(--info)" },
  codemod:  { label: "codemod",  glyph: "↻", color: "oklch(0.7 0.12 290)" },
  review:   { label: "review",   glyph: "◇", color: "var(--success)" },
  docs:     { label: "docs",     glyph: "¶", color: "oklch(0.7 0.06 90)" },
};
const SOURCE_TAG = {
  "first-party": { label: "first-party", cls: "amber" },
  team:          { label: "team",        cls: "info" },
  imported:      { label: "imported",    cls: "" },
  community:     { label: "community",   cls: "" },
};

// Vendored from `./skillStyles` (real file, unchanged pure CSSProperties builders).
function tintBg(hue, t = 88) { return `color-mix(in oklch, ${hue}, transparent ${t}%)`; }
function pill(hue, plain = false) {
  const base = { fontFamily: "var(--mono)", fontSize: 9.5, padding: "2px 7px", borderRadius: 99, lineHeight: 1.1, whiteSpace: "nowrap", display: "inline-flex", alignItems: "center" };
  if (plain) return { ...base, background: tintBg("var(--fg-dim)"), border: "1px solid " + tintBg("var(--fg-dim)", 80), color: "var(--fg-muted)" };
  return { ...base, background: tintBg(hue), border: `1px solid ${tintBg(hue, 74)}`, color: hue };
}
function glyphTile(kind) {
  const c = KIND[kind].color;
  return { width: 24, height: 24, flex: "0 0 auto", display: "flex", alignItems: "center", justifyContent: "center", borderRadius: 6, fontFamily: "var(--mono)", fontSize: 12, color: c, background: `color-mix(in oklch, ${c} 22%, var(--bg-elev))`, border: `1px solid ${tintBg(c, 70)}` };
}
function sourcePill(src) {
  return src === "team" ? pill("var(--info)") : src === "imported" ? pill("var(--accent)") : pill("", true);
}

// Vendored from `./lib/skills` (real files: skillsSession.ts + skillGroups.ts — pure logic, unchanged).
function sessionSkillState(skill, projectId, override, groupSkillIds) {
  if (!skill.enabled) return { skill, on: false, reason: "disabled", overridden: false };
  const inScope = skill.projects.length === 0 || (!!projectId && skill.projects.includes(projectId));
  const viaGroup = groupSkillIds?.has(skill.id) ?? false;
  const baseOn = inScope || viaGroup;
  const removed = override?.remove?.includes(skill.id) ?? false;
  const added = override?.add?.includes(skill.id) ?? false;
  const on = removed ? false : added ? true : baseOn;
  const overridden = on !== baseOn;
  let reason;
  if (overridden) reason = on ? "added" : "removed";
  else if (on) reason = inScope ? (skill.pinned ? "pinned" : skill.projects.length === 0 ? "global" : "project") : "group";
  else reason = "out-of-scope";
  return { skill, on, reason, overridden };
}
function expandGroups(groupIds, groups) {
  const byId = new Map(groups.map((g) => [g.id, g]));
  const out = new Set();
  for (const gid of groupIds) for (const sid of byId.get(gid)?.skillIds ?? []) out.add(sid);
  return [...out];
}
function groupSkillCount(group, all) {
  const ids = new Set(all.map((s) => s.id));
  return group.skillIds.filter((id) => ids.has(id)).length;
}

/** Color + copy for each effective-state reason (the row's "why" pill). */
const REASON_META = {
  global:        { label: "on · global",        hue: "var(--success)", hint: "" },
  project:       { label: "on · project-scoped", hue: "var(--info)",    hint: "" },
  pinned:        { label: "on · pinned",         hue: "var(--success)", hint: "auto-offered to the fleet" },
  group:         { label: "on · group",          hue: "var(--violet, oklch(0.7 0.12 290))", hint: "enabled by a task group" },
  added:         { label: "added",               hue: "var(--accent)",  hint: "override · normally out of scope" },
  removed:       { label: "removed",             hue: "var(--danger)",  hint: "override · normally on" },
  "out-of-scope":{ label: "off · out of scope",  hue: "var(--fg-dim)",  hint: "" },
  disabled:      { label: "off · disabled",      hue: "var(--fg-dim)",  hint: "disabled in the library" },
};

// Preview-only sample data, standing in for the real `useAppStore()` reads (skills/skillGroups/
// sessionSkillOverrides/sessionSkillGroups) — app-internal, unresolvable here.
const SAMPLE_SKILLS = [
  { id: "sk1", name: "SOC 2 attestation", kind: "review", source: "first-party", desc: "Checks compliance evidence before shipping.", tools: ["Read", "Grep"], enabled: true, projects: [], pinned: true },
  { id: "sk2", name: "React scaffold", kind: "scaffold", source: "team", desc: "Bootstraps a new feature module.", tools: ["Write"], enabled: true, projects: ["proj-1"], pinned: false },
  { id: "sk3", name: "i18n codemod", kind: "codemod", source: "imported", desc: "Extracts hardcoded strings.", tools: ["Edit", "Bash"], enabled: true, projects: [], pinned: false },
  { id: "sk4", name: "API docs writer", kind: "docs", source: "community", desc: "Drafts endpoint reference docs.", tools: ["Write"], enabled: false, projects: [], pinned: false },
];
const SAMPLE_GROUPS = [
  { id: "g1", name: "Ship checklist", hue: "var(--accent)", skillIds: ["sk1", "sk3"] },
];

export function SessionSkillsModal({ sessionKey = "pane-1", projectId = "proj-1", sessionLabel = "worker · payments-api · stream:checkout", onClose = () => {} }) {
  const [skills] = useState(SAMPLE_SKILLS);
  const [skillGroups] = useState(SAMPLE_GROUPS);
  const [override, setOverride] = useState({ add: [], remove: [] });
  const [sessionGroups, setSessionGroups] = useState(["g1"]);

  const setSessionSkill = (key, skillId, choice) => {
    setOverride((o) => {
      const add = new Set(o.add), remove = new Set(o.remove);
      add.delete(skillId); remove.delete(skillId);
      if (choice === "on") add.add(skillId);
      else if (choice === "off") remove.add(skillId);
      return { add: [...add], remove: [...remove] };
    });
  };
  const setSessionSkillGroup = (key, groupId, on) => {
    setSessionGroups((gs) => (on ? [...gs, groupId] : gs.filter((g) => g !== groupId)));
  };
  const resetSessionSkills = () => { setOverride({ add: [], remove: [] }); setSessionGroups([]); };

  const [query, setQuery] = useState("");
  const [tab, setTab] = useState("assigned");

  const groupIds = sessionGroups ?? [];
  const groupSkillIds = useMemo(() => new Set(expandGroups(groupIds, skillGroups)), [groupIds, skillGroups]);

  const states = useMemo(
    () => skills.map((s) => sessionSkillState(s, projectId, override, groupSkillIds)),
    [skills, projectId, override, groupSkillIds],
  );
  const availCount = states.filter((st) => st.on).length;
  const overrides = states.filter((st) => st.overridden);

  const q = query.trim().toLowerCase();
  const matches = (st) => !q || (st.skill.name + " " + st.skill.desc + " " + st.skill.tools.join(" ")).toLowerCase().includes(q);
  const overrideRows = overrides.filter(matches);
  const restRows = states.filter((st) => !st.overridden && (tab === "all" || st.on)).filter(matches);

  const flip = (st) => setSessionSkill(sessionKey, st.skill.id, st.on ? "off" : "on");

  function SkillRow({ st }) {
    const m = REASON_META[st.reason];
    return (
      <Grid className="sess-skill-row" data-skill-id={st.skill.id} cols="24px 1fr auto" align="center" gap={12} style={{ padding: "9px 20px", borderBottom: "1px solid var(--border-soft)",
        background: st.overridden ? "color-mix(in oklch, var(--accent), transparent 93%)" : "transparent",
        boxShadow: st.overridden ? (st.reason === "removed" ? "inset 2px 0 0 var(--danger)" : "inset 2px 0 0 var(--accent)") : "none" }}>
        <Box as="span" style={glyphTile(st.skill.kind)}>{KIND[st.skill.kind].glyph}</Box>
        <Stack gap={2} style={{ minWidth: 0 }}>
          <Row gap={7}>
            <Text as="span" mono size={12} style={{ color: "var(--fg)", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{st.skill.name}</Text>
            <Box as="span" style={sourcePill(st.skill.source)}>{SOURCE_TAG[st.skill.source].label}</Box>
          </Row>
          <Row gap={6}>
            <Box as="span" style={pill(m.hue, m.hue === "var(--fg-dim)")}>{m.label}</Box>
            {m.hint && <Text as="span" size={10.5} tone="dim">{m.hint}</Text>}
          </Row>
        </Stack>
        <Row gap={10}>
          {st.overridden && <Text as="span" size={10.5} tone="dim" onClick={() => setSessionSkill(sessionKey, st.skill.id, "inherit")} style={{ cursor: "pointer", textDecoration: "underline", textUnderlineOffset: 2 }}>reset</Text>}
          <Toggle size="sm" className="sess-toggle" on={st.on} onClick={() => flip(st)} />
        </Row>
      </Grid>
    );
  }

  return (
    <ModalCard
      title="Skills for this session" onClose={onClose}
      align="start" blur={false} width={840} maxHeight="calc(100vh - 120px)"
      bodyStyle={{ flex: 1, padding: "6px 0 0" }}
      footStyle={{ gap: 12, padding: "12px 20px", background: "var(--bg-canvas)" }}
      headExtra={
        <>
          <Row gap={8} wrap style={{ marginTop: 9 }}>
            <Text as="span" mono size={11.5} tone="muted">{sessionLabel || sessionKey}</Text>
            <Box as="span" style={{ flex: 1 }} />
            <Text as="span" size={11.5} tone="muted"><b className="mono" style={{ color: "var(--fg)" }}>{availCount}</b> available · <b className="mono" style={{ color: "var(--accent)" }}>{overrides.length}</b> overrides</Text>
          </Row>
          <Row gap={10} style={{ marginTop: 13 }}>
            <SearchField
              value={query}
              onChange={setQuery}
              placeholder="Search skills..."
              style={{ flex: 1, height: 30, background: "var(--bg-canvas)", borderRadius: "var(--r-md)" }}
            />
            <Row align="stretch" style={{ height: 30, border: "1px solid var(--border)", borderRadius: "var(--r-md)", overflow: "hidden" }}>
              {[["assigned", `Assigned (${availCount})`], ["all", `All (${skills.length})`]].map(([t, lbl], i) => (
                <Row key={t} onClick={() => setTab(t)} style={{ padding: "0 11px", fontSize: 11, cursor: "pointer", background: tab === t ? "var(--bg-elev2)" : "transparent", color: tab === t ? "var(--fg)" : "var(--fg-dim)", borderRight: i === 0 ? "1px solid var(--border)" : "none" }}>{lbl}</Row>
              ))}
            </Row>
            <Button onClick={() => resetSessionSkills(sessionKey)} style={{ height: 30, padding: "0 11px", border: "1px solid var(--border)", background: "var(--bg-elev)", color: "var(--fg-muted)", whiteSpace: "nowrap" }}>↺ Reset all</Button>
          </Row>
          {skillGroups.length > 0 && (
            <Row gap={8} wrap style={{ marginTop: 11 }}>
              <Text as="span" mono size={9.5} tone="dim" style={{ textTransform: "uppercase", letterSpacing: ".08em" }}>⬡ Quick-add a task group</Text>
              {skillGroups.map((g) => { const on = groupIds.includes(g.id); return (
                // eslint-disable-next-line no-restricted-syntax -- bespoke per-group pill toggle with hue-tinted inline styling, not a .btn control
                <button key={g.id} onClick={() => setSessionSkillGroup(sessionKey, g.id, !on)} style={{ display: "inline-flex", alignItems: "center", gap: 6, height: 24, padding: "0 10px", borderRadius: 99, fontSize: 11, cursor: "pointer", whiteSpace: "nowrap", border: "1px solid " + (on ? g.hue : "var(--border)"), background: on ? `color-mix(in oklch, ${g.hue}, transparent 85%)` : "transparent", color: on ? g.hue : "var(--fg-muted)" }}>
                  <Box as="span" style={{ opacity: 0.75 }}>⬡</Box>{g.name}<Text as="span" mono size={9.5} style={{ opacity: 0.7 }}>{on ? "✓" : "+" + groupSkillCount(g, skills)}</Text>
                </button>
              ); })}
            </Row>
          )}
        </>
      }
      foot={
        <>
          <Text as="span" size={11} tone="dim" style={{ lineHeight: 1.4 }}>Written as <Text as="span" mono tone="muted">.claude/skills/&lt;slug&gt;/SKILL.md</Text> on next relaunch.</Text>
          <Box as="span" style={{ flex: 1 }} />
          <Button variant="primary" onClick={onClose} style={{ height: 31, padding: "0 16px", border: "1px solid var(--accent-dim)", color: "var(--bg-canvas)", fontSize: 12 }}>Done</Button>
        </>
      }
    >
      {overrideRows.length > 0 && (
        <>
          <Text as="div" mono size={9.5} tone="accent" style={{ padding: "9px 20px 5px 20px", textTransform: "uppercase", letterSpacing: ".08em" }}>Overrides · {overrideRows.length}</Text>
          {overrideRows.map((st) => <SkillRow key={st.skill.id} st={st} />)}
        </>
      )}
      <Text as="div" mono size={9.5} tone="dim" style={{ padding: "13px 20px 5px 20px", textTransform: "uppercase", letterSpacing: ".08em" }}>
        {tab === "assigned" ? `Assigned to this session · ${restRows.length}` : `All skills · ${restRows.length}`}
      </Text>
      {restRows.map((st) => <SkillRow key={st.skill.id} st={st} />)}
      {restRows.length === 0 && overrideRows.length === 0 && (
        <Text as="div" tone="dim" size={12} style={{ padding: "40px 20px", textAlign: "center" }}>No skills match.</Text>
      )}
    </ModalCard>
  );
}
